recipes.code:
{
  "inputs": [
    {
      "id": "yungle-api-key",
      "type": "promptString",
      "description": "A Yungle API key from https://yungle.co/dashboard/settings/api. Reading is free on any account; give the key read scopes only — this server has no tool that writes.",
      "password": true
    }
  ],
  "servers": {
    "yungle": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "yungle-mcp@0.1.2"
      ],
      "env": {
        "YUNGLE_API_KEY": "${input:yungle-api-key}",
        "YUNGLE_API_URL": "<yungle-api-url>"
      }
    }
  }
}
